/**
 * The real logos that stand in the Experience room, traced from the
 * supplied images (scratchpad trace.py) into stacked colour layers.
 *
 * Each logo is a list of layers from the bottom up, each a path in a 512 box
 * (y down, even-odd) in the logo's own colour. A layer's outline includes the
 * layers above it, so the stack is solid, and is extruded one slab on another
 * (BrandLogo.tsx), which gives a real inlay rather than a picture on a card.
 * The marks belong to their organisations: NextRound, Palmy AI, Royal
 * Holloway, Insanity Radio, J D Wetherspoon and Fiverr.
 */
export type BrandLogoId = "nextround" | "palmy" | "rhul" | "insanity" | "wetherspoon" | "fiverr";

/** Every brand that stands in a case: the traced ones, and the International Society, whose badge is printed rather than traced. */
export type BrandId = BrandLogoId | "intsoc";
export const BRAND_IDS: readonly BrandId[] = ["nextround", "palmy", "rhul", "insanity", "wetherspoon", "fiverr", "intsoc"];

export type BrandLayer = { name: string; color: string; d: string };
export type BrandLogoData = { w: number; h: number; layers: BrandLayer[] };

